1085		markHealth(t, r, "svc", "a", 1, 3, true, "")
1086		if out := selectedWithSession(t, r, "svc", 1, "s"); out.InstanceID != "a" || out.Sequence != 3 {
1087			t.Fatalf("recovered binding should be reused: %+v", out)
1088		}
