130			t.Fatalf("result 9 plain select wraps to i1 regardless of resubmission order: %+v", r)
131		}
132	
133		// 10: identical content does not bypass the revision gate. The list is
134		// valid (reordered again) but expectedRevision 2 mismatches the current 1:
135		// conflict, with the reason and both revisions, and no false success.
136		if r := got.Results[10]; r.OK || r.Error != "conflict" ||
137			r.Reason != `service "svc" is at revision 1, not 2` ||
138			r.Revision != 1 || !hasRevisionPair(r, 2, 1) {
