142		// 11: the conflict cleared neither the session binding nor the cursor.
143		if r := got.Results[11]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
144			t.Fatalf("result 11 session must survive the conflict: %+v", r)
145		}
146		// 12: a plain select continues just after the last real rotation (i1 from
147		// result 9) to i2 instead of restarting at the smallest id.
148		if r := got.Results[12]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:2" || r.Sequence != 22 || r.Revision != 1 {
