	registerService(t, r, "svc", 0, []Instance{
		{ID: "i1", Address: "api.example:8080"},
		{ID: "i2", Address: "h2:2"},
	})
	markHealth(t, r, "svc", "i1", 1, 5, true, "")
	markHealth(t, r, "svc", "i2", 1, 6, true, "")

